-- Lliçons fixes de Fonètica, elocució i ortografia del C1 (botó «Aprendre lliçó»).
-- Com les del B2, cada lliçó és una adaptació didàctica de nivell C1
-- redactada a partir de:
--   - l'abast de cada contingut del C1 (Quadern C1 de la JQCV, 3.2.1), descrit en
--     20261014150000_practice_fonetica_c1.sql;
--   - les regles d'Ortologia i Ortografia de la GVB i la GNV de l'AVL, descarregades una sola vegada en assets-src/avl/.
-- El contingut es guarda en metadata.lesson (mateix format que en el B1 i el B2). La migració de
-- continguts (20261014150000) conserva metadata.lesson si es torna a aplicar.
-- Tornar a aplicar este fitxer no canvia res més.

UPDATE public.resources r SET
  metadata = coalesce(r.metadata, '{}'::jsonb) || jsonb_build_object('lesson', l.lesson)
FROM jsonb_to_recordset($data$[
  {"type": "c1_fon_elocucio", "lesson": {"intro": "Aprendràs els processos fonològics de l'estàndard (ensordiments, sonoritzacions, assimilacions, geminacions), quines pronunciacions col·loquials cal evitar en l'àmbit formal i com l'entonació marca la modalitat i els incisos.", "blocks": [{"title": "Ensordiment i sonorització", "text": "Les oclusives finals (*b/p*, *d/t*, *g/c*) es pronuncien **sordes** davant de pausa, de vocal i de consonant sorda: *fre[t]*, *demago[k]*, *alju[p]*, *verd obscur* [vɛ́ɾt]. Només es fan **sonores** davant de consonant sonora: *club d'amics* [klúb]. En canvi, *s*, *ç*, *-ix*, *-ig* i *-tx* finals es fan **sonores davant de vocal** i de consonant sonora: *el[z] autors*, *roig encés* [rɔ́ʤ]. La *t* de *-nt* es manté davant de vocal: *vint hòmens*.", "table": {"head": ["context", "oclusiva final", "s, ç, ix, ig, tx"], "rows": [["pausa", "sorda: *fred* [t]", "sorda: *braç* [s]"], ["vocal", "sorda: *club animat* [p]", "sonora: *els autors* [z]"], ["consonant sonora", "sonora: *club d'amics* [b]", "sonora: *peix blau* [ʒ]"], ["consonant sorda", "sorda: *sac ple* [k]", "sorda: *peix cru* [ʃ]"]]}}, {"title": "Assimilació, geminació i alternança vocàlica", "text": "Per **assimilació**, una consonant pren trets de la següent: *ta[m]mateix*, *u[m] pa*. La preposició *amb* sona [amb] davant de vocal i [am] o [an] davant de consonant. Les grafies *mm* i *pp* representen **geminades**: *i[mm]inent*, *ca[pp]are*; en canvi, en *nn* s'emmudix la primera *n* (*innocent*). En *tl* patrimonial (*ametla*) és preferible la geminada; *tm* (*setmana*) és simple. En molts verbs la vocal del radical **alterna** segons que siga tònica o àtona.", "table": {"head": ["tònica", "àtona"], "rows": [["*vull*, *vullgues*", "*volem*, *volgueres*"], ["*cus*, *cuses*", "*cosim*, *cosir*"], ["*cull*, *culls*", "*collim*, *collir*"]]}}, {"title": "Metàtesis, dissimilacions i assimilacions no formals", "text": "En els àmbits formals cal evitar les **metàtesis** (canvi de lloc d'un so) i les **dissimilacions** pròpies de la parla espontània. La *r* ha d'anar en la síl·laba que li correspon i les dues *i* de *civil* s'han de mantindre.", "watch": [{"wrong": "*crompar*", "right": "comprar"}, {"wrong": "*pedricar*", "right": "predicar"}, {"wrong": "*quidrar* [kiðɾáɾ]", "right": "cridar"}, {"wrong": "*sevil*, *vesita*", "right": "civil, visita"}]}, {"title": "Sons suprimits, afegits o modificats", "text": "Tampoc són recomanables la **supressió** de sons (*d* i *g* intervocàliques, *r* de l'infinitiu davant de pronom, *n* de *cons-*), l'**addició** de sons (*t* o *r* finals) ni la **modificació** de consonants: *j* com a [j] (fora de *ja* i *jo*), *l* culta palatalitzada, *n* inicial palatal o reducció de [kwa].", "watch": [{"wrong": "*aülla*, *roa*, *cadia*", "right": "agulla, roda, cadira"}, {"wrong": "*nyèrvit*, *prèmit*, *creurer*", "right": "nervi, premi, creure"}, {"wrong": "*Iordi*, *lliteratura*", "right": "Jordi, literatura"}, {"wrong": "*consevol*, *portà-li*", "right": "qualsevol, portar-li"}]}, {"title": "Estàndard i varietats dialectals", "text": "L'AVL distingix entre pronunciacions **pròpies de l'estàndard**, **acceptables** en el territori on són pròpies i **no recomanables**. Són acceptables, per exemple, *pilot[ɔ]*, *tel[ɛ]*, *ell cant[e]*, *ca(i)xa*, *[ku]sir*, la neutralització *b/v* (tot i que és preferible distingir-les) o l'emmudiment de la *r* final de *cantar*. Són pròpies, i no només acceptables, *p(r)endre* o *dima(r)ts*.", "table": {"head": ["pròpia de l'estàndard", "acceptable on és pròpia", "no recomanable"], "rows": [["*p(r)endre*, *dima(r)ts*", "*pilot[ɔ]*, *canta(r)*", "*parla(v)es*"], ["*Joan* [ʤuán]", "*viure* [bíwɾe]", "*platja* [pláʧa]"]]}}, {"title": "Entonació i comunicació no verbal", "text": "L'**entonació** distingix la modalitat: una interrogativa total no té cap interrogatiu, només el contorn melòdic (*Has vist la carta?*), i pot dur un *que* expletiu (*Que et fa mal la panxa?*). Les relatives explicatives i els incisos es pronuncien entre **inflexions tonals**, que l'escriptura marca amb comes. En textos per a ser llegits, el signe d'obertura (¿, ¡) ajuda a fer la inflexió en el lloc just. Gestos, mirada i postura han de **reforçar** el missatge.", "examples": ["Els xiquets, que no van jugar, no han dit res.", "¿Pot justificar-se en algun cas la violència —es preguntà el conferenciant—?"]}], "remember": ["Oclusives finals sordes (*fre[t]*, *verd obscur* [t]); sonores només davant de consonant sonora.", "*S*, *ç*, *-ix*, *-ig*, *-tx* finals sonen sonores davant de vocal: *el[z] autors*.", "*Ta[m]mateix*, *i[mm]inent*, però *innocent* amb una sola [n].", "Res de *crompar*, *aülla*, *nyèrvit*, *Iordi*, *lliteratura* o *consevol* en registre formal.", "L'entonació marca les interrogatives totals i els incisos; les comes la reflectixen."], "sources": [{"gram": "GNV", "section": "1.1", "title": "Introducció", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_1"}, {"gram": "GVB", "section": "1.2.2.2", "title": "Pronunciacions acceptables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=1_2_2_2"}, {"gram": "GVB", "section": "2.1.3", "title": "Pronunciacions no recomanables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_1_3"}, {"gram": "GVB", "section": "2.5.3", "title": "Pronunciacions no recomanables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_5_3"}, {"gram": "GVB", "section": "2.6.3", "title": "Pronunciacions no recomanables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_6_3"}, {"gram": "GVB", "section": "2.7.1", "title": "Pronunciacions recomanables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_7_1"}, {"gram": "GVB", "section": "3.2.1", "title": "Les consonants b/p, d/t i g/c", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=3_2_1"}, {"gram": "GVB", "section": "3.2.2", "title": "El grup ‑nt", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=3_2_2"}, {"gram": "GNV", "section": "1.3.2.5", "title": "Les consonants laterals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_5"}, {"gram": "GNV", "section": "1.4.2.1", "title": "Les consonants oclusives en posició final", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_4_2_1"}, {"gram": "GNV", "section": "1.4.2.2", "title": "Les consonants fricatives i africades en posició final", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_4_2_2"}, {"gram": "GNV", "section": "7.4", "title": "Els signes d'entonació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=7_4"}, {"gram": "GNV", "section": "25.2", "title": "Els interrogatius i les oracions interrogatives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=25_2"}]}},
  {"type": "c1_fon_vocals", "lesson": {"intro": "Aprendràs a escriure les vocals en paraules difícils (*món/mundial*, *afaitar*, *metre*), a evitar vocals col·loquials en el registre formal i a separar síl·labes en derivats, compostos i grups de consonants.", "blocks": [{"title": "Patrimonials i derivats cultes", "text": "Moltes paraules **patrimonials** tenen *o* o *e* allà on el seu derivat **culte** conserva la vocal llatina *u* o *i*. Per això no s'ha de traslladar la vocal de la paraula base al cultisme: *món* però *mundial*; *hòmens* però *humà*; *corba* però *curvilini* (que, a més, canvia *b* per *v*).", "table": {"head": ["patrimonial", "culte"], "rows": [["*món*", "*mundial*, *mundà*"], ["*home*, *hòmens*", "*humà*, *humanitat*"], ["*corba*", "*curvilini*"], ["*jove*", "*juvenil*"], ["*molt*", "*multitud*"], ["*boca*", "*bucal*"], ["*creu*", "*crucial*"]]}}, {"title": "Vocals diferents d'altres llengües", "text": "Algunes paraules s'escriuen amb una vocal diferent de la del castellà o d'altres llengües, i sovint també de la pronunciació habitual. Cal fixar-ne la forma: amb **a** (*afaitar*, *ambaixada*, *avaluar*, *avaria*, *rancor*), amb **e** (*assemblea*, *monestir*, *metre*), amb **o** (*avorrir*, *complir*, *sofrir*, *polir*, *capítol*, *sospir*) i amb **u** (*muntar*, *suportar*, *turment*, *suborn*, *bufetada*).", "watch": [{"wrong": "*avurrir-se*, *afeitar-se*", "right": "avorrir-se, afaitar-se"}, {"wrong": "*metro* (mesura), *línea*", "right": "metre, línia"}, {"wrong": "*cumplir*, *montar*", "right": "complir, muntar"}]}, {"title": "Vocals col·loquials que cal evitar", "text": "En el registre formal no són recomanables la diftongació de la *o* inicial (*aubrir*), el tancament de la *e* en contacte amb palatal (*dixar*, *minjar*), la *u* pronunciada [o] (*joliol*, *fogir*), l'elisió de la *i* de *-iència* ni les formes verbals amb vocal canviada (*puguera*). Són **acceptables** on són pròpies, en canvi, [u] en *cosir*, *collir* o *obert*.", "watch": [{"wrong": "*aubrir*, *aufegar*", "right": "obrir, ofegar"}, {"wrong": "*puguera*", "right": "poguera"}, {"wrong": "*dixar*, *sinyor*", "right": "deixar, senyor"}, {"wrong": "*pacència*", "right": "paciència"}]}, {"title": "Diftongs, triftongs i hiats", "text": "Un **diftong** unix vocal i semivocal en una síl·laba (*ai-re*, *qua-tre*); un **triftong** té una vocal entre dues semivocals (*cre-ieu*, *guai-tar*); en un **hiat** les vocals pertanyen a síl·labes diferents (*ve-ï-na*, *ma-nu-al*). En *història* o *gràcia* el final es pronuncia normalment com a diftong; el hiat és de registres molt formals. *Ui* pot ser creixent o decreixent (*buit*), però és creixent en *hui* i *huit*.", "examples": ["*hie-na*, *bo-ia*: i entre vocals o inicial forma diftong creixent.", "*aquàrium*, *harmònium*: -iu- sense diftong en aquests cultismes."]}, {"title": "Separar síl·labes: dígrafs i lletres compostes", "text": "Es **separen** *rr*, *ss*, *sc*, *l·l* (perdent el punt), *tj*, *tg*, *tx*, *tl*, *tll*, *tm*, *tn*, *tz*, *mm* i *nn*. **No** se separen mai *gu*, *qu*, *ll*, *ny* ni *ig*.", "table": {"head": ["se separen", "no se separen"], "rows": [["*car-rer*, *es-ce-na*, *vil-la*", "*jo-guet*, *pa-quet*"], ["*set-ma-na*, *cot-na*, *set-ze*", "*pe-nya*, *pe-lle-ter*"], ["*ho-rit-zó*, *in-no-cent*, *im-mers*", "*ma-reig*, *es-que-ma*"]]}}, {"title": "Separar síl·labes en derivats i compostos", "text": "Els **constituents** d'un compost o d'un derivat amb prefix se separen, encara que la consonant final del primer element vaja davant de vocal. En la partició a final de línia, a més, no s'ha de deixar cap lletra sola ni separar l'apòstrof.", "watch": [{"wrong": "*be-nes-tar*", "right": "ben-es-tar"}, {"wrong": "*de-sai-re*", "right": "des-ai-re"}, {"wrong": "*vo-sal-tres*", "right": "vos-al-tres"}, {"wrong": "*i-nex-pert*, *a-dhe-rir*", "right": "in-ex-pert, ad-he-rir"}]}], "remember": ["Patrimonial amb *o*/*e*, culte amb *u*/*i*: *món*/*mundial*, *home*/*humà*, *corba*/*curvilini*.", "*Avorrir*, *afaitar*, *metre*, *línia*, *complir*, *muntar*: fixa'n la vocal.", "En registre formal: *obrir*, *poguera*, *deixar*, *juliol*, *paciència*.", "Se separen *rr*, *ss*, *l·l*, *tm*, *tz*, *nn*...; mai *gu*, *qu*, *ll*, *ny*, *ig*.", "Prefixos i compostos se separen pels seus elements: *ben-es-tar*, *des-ai-re*, *vos-al-tres*."], "sources": [{"gram": "GVB", "section": "1.2.2.2", "title": "Pronunciacions acceptables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=1_2_2_2"}, {"gram": "GVB", "section": "1.2.2.3", "title": "Pronunciacions no recomanables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=1_2_2_3"}, {"gram": "GVB", "section": "1.2.3.1", "title": "Pronunciacions recomanables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=1_2_3_1"}, {"gram": "GVB", "section": "1.2.3.2", "title": "Pronunciacions no recomanables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=1_2_3_2"}, {"gram": "GVB", "section": "5.1.2", "title": "Normes de separació sil·làbica", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=5_1_2"}, {"gram": "GVB", "section": "5.2.2", "title": "Classificació dels diftongs", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=5_2_2"}, {"gram": "GVB", "section": "6.2", "title": "Les grafies a i e", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_2"}, {"gram": "GVB", "section": "6.3", "title": "Les grafies o i u", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_3"}, {"gram": "GNV", "section": "1.2.2.3", "title": "Criteris particulars de pronunciació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_2_2_3"}, {"gram": "GNV", "section": "1.2.3", "title": "Els grups vocàlics", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_2_3"}, {"gram": "GNV", "section": "3.1.2", "title": "Normes de separació sil·làbica", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=3_1_2"}, {"gram": "GNV", "section": "3.2.1", "title": "Conceptes bàsics", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=3_2_1"}]}},
  {"type": "c1_fon_accentuacio", "lesson": {"intro": "Aprendràs a aplicar les regles d'accentuació en casos difícils: el timbre obert o tancat, les excepcions, la e tancada valenciana, els diacrítics, els compostos i derivats i els cultismes i préstecs.", "blocks": [{"title": "Regles generals i timbre", "text": "S'accentuen les **agudes** acabades en vocal, vocal + *s*, *-en* o *-in* (*cantó*, *arròs*, *entén*), però no si acaben en semivocal (*comboi*, *parlareu*); les **planes** que no acaben així (*préstec*, *córrer*, *exàmens*) i **totes** les esdrúixoles. L'accent **agut** marca *i*, *u*, *e* i *o* tancades; el **greu**, *a*, *e* i *o* obertes. En els verbs en *-iar* l'accent recau en la *i* (*canvia*); *aurèola* és esdrúixola i *rèptil*, *tèxtil* i *medul·la*, planes.", "table": {"head": ["paraula", "per què"], "rows": [["*entén*, *mantín*", "aguda en *-en*, *-in*"], ["*examen* / *exàmens*", "plana en *-en* / en *-ens*"], ["*comboi*, *espai*", "aguda en semivocal: sense accent"]]}}, {"title": "La e tancada valenciana", "text": "Segons la pronunciació valenciana, s'usa l'**accent agut** en *café*, *anglés*, *aprén*, *conéixer*, *convéncer*, *fényer*, *féiem*, *créieu*, *pésol*, *terratrémol* o *aniré*. Moltes d'estes paraules admeten també l'accent greu d'altres parlars (*cafè*, *conèixer*), però n'hi ha que **només** porten accent agut.", "table": {"head": ["admeten també è", "només é"], "rows": [["*conéixer*, *paréixer*", "*créixer*, *néixer*"], ["*aprén*, *comprén*", "*atén*, *entén*, *pretén*, *encén*"], ["*café*, *seré*", "*puré*, *consomé*, *suflé*"], ["*pésol*, *trévol*", "*cérvol*"]]}}, {"title": "Excepcions: é i ó on s'esperaria è i ò", "text": "La *e* sol ser oberta si la síl·laba següent té *i* o en les esdrúixoles, però és **tancada** en *església*, *Dénia*, *séquia*, *sépia*, *llémena*, *sémola*, *Énguera* o *cérvola*. La *o* de les esdrúixoles sol ser oberta, però és **tancada** en *fórmula*, *góndola*, *pólvora*, *tómbola* i *tórtora*. Distingix també *exclòs* (de *cloure*) de *difós* (de *fondre*), i *terròs* (substantiu) de *terrós* (adjectiu).", "examples": ["La **pólvora** de la mascletà.", "Una **séquia** que travessa l'horta d'**Énguera**."]}, {"title": "Accent greu amb e tancada: què, perquè, València", "text": "Per a evitar divergències entre parlars, porten **accent greu** malgrat pronunciar-se amb *e* tancada *què*, *perquè*, *València* i alguns cultismes (*època*, *sèrie*, *èter*, *sèsam*, *bèstia*). La conjunció *però* admet dues pronunciacions: [peɾɔ́] i [péɾo]. Recorda la diferència entre *perquè* (conjunció) i *per què* (preposició + interrogatiu o relatiu).", "watch": [{"wrong": "*Perquè no vens?*", "right": "Per què no vens?"}, {"wrong": "*el tema de que parlàvem*", "right": "el tema de què parlàvem"}]}, {"title": "Diacrítics, compostos i adverbis en -ment", "text": "Els **diacrítics** distingixen homògrafs: *bé/be*, *déu/deu*, *és/es*, *mà/ma*, *més/mes*, *món/mon*, *pèl/pel*, *què/que*, *sé/se*, *sí/si*, *sòl/sol*, *són/son*, *té/te*, *ús/us*, *vós/vos*. En compostos **amb guionet** cada element manté el seu accent (*pèl-roig*, *sud-americà*, *ciència-ficció*); en compostos **fusionats** s'aplica la regla a la paraula sencera (*fisicoquímic*, *quilòmetre*) i es perd el diacrític (*rodamon*, *subsol*). Els adverbis en *-ment* porten l'accent de l'adjectiu: *útilment*, però *subtilment*.", "watch": [{"wrong": "*rodamón*, *físicoquímic*", "right": "rodamon, fisicoquímic"}, {"wrong": "*utilment*", "right": "útilment"}]}, {"title": "Cultismes, préstecs i topònims", "text": "Els préstecs **adaptats** van en redona i s'accentuen segons les regles generals: *líder*, *escàner*, *míting*, *bàrman*, *cupé*. També els llatinismes adaptats (*currículum*, *referèndum*, *quòrum*, *superàvit*); els **no adaptats** van en cursiva i sense accent (*in memoriam*). Els topònims adaptats s'accentuen com el lèxic general (*París*, *Mònaco*, *Hèlsinki*) i les majúscules també porten accent (*ÀFRICA*, *DÉNIA*).", "examples": ["Va presentar el **currículum** en el **míting**.", "*Alcalá de Henares* manté l'ortografia castellana perquè no està adaptat."]}], "remember": ["Agudes en vocal, vocal + *s*, *-en*, *-in*; planes en la resta; esdrúixoles sempre.", "*Créixer*, *néixer*, *entén*, *atén*, *puré* i *cérvol* només amb é.", "Excepcions amb é/ó: *església*, *Dénia*, *llémena*, *fórmula*, *pólvora*, *tómbola*, *tórtora*.", "*Què*, *perquè*, *València*, *època*: accent greu, e tancada; *però* admet dues pronunciacions.", "Amb guionet es manté l'accent (*pèl-roig*, *sud-americà*); fusionat, no (*rodamon*, *fisicoquímic*).", "*-ment* conserva l'accent de l'adjectiu: *útilment*, *subtilment*."], "sources": [{"gram": "GVB", "section": "7.2", "title": "Regles generals d'accentuació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=7_2"}, {"gram": "GVB", "section": "7.3", "title": "L'accentuació de les vocals e i o", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=7_3"}, {"gram": "GVB", "section": "7.4", "title": "Observacions sobre l'accentuació de la vocal e", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=7_4"}, {"gram": "GVB", "section": "7.7", "title": "L'accentuació diacrítica", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=7_7"}, {"gram": "GVB", "section": "7.8", "title": "L'accentuació de paraules compostes", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=7_8"}, {"gram": "GVB", "section": "7.9", "title": "L'accentuació d'adverbis en ‑ment", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=7_9"}, {"gram": "GVB", "section": "7.10", "title": "L'accentuació de paraules estrangeres", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=7_10"}, {"gram": "GVB", "section": "7.11", "title": "L'accentuació de paraules o expressions llatines", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=7_11"}, {"gram": "GVB", "section": "7.12", "title": "L'accentuació de topònims", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=7_12"}, {"gram": "GNV", "section": "1.2.1.3", "title": "La distribució de la e i la o obertes", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_2_1_3"}, {"gram": "GNV", "section": "1.5", "title": "L'accentuació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_5"}, {"gram": "GNV", "section": "5.1.1", "title": "Regles generals d'accentuació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=5_1_1"}, {"gram": "GNV", "section": "5.1.2", "title": "Observacions sobre l'accentuació de les ee", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=5_1_2"}, {"gram": "GNV", "section": "5.1.3", "title": "L'accentuació diacrítica", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=5_1_3"}]}},
  {"type": "c1_fon_dieresi_guionet", "lesson": {"intro": "Aprendràs els casos difícils de la dièresi (derivats cultes, estalvi i excepcions), quan porten o no guionet les paraules compostes i prefixades, i com canvia la forma dels pronoms febles segons la posició i la combinació.", "blocks": [{"title": "Dièresi: casos avançats", "text": "A més de *güe*, *qüi* i dels hiats sense accent (*veïna*, *taüt*), la dièresi apareix en **derivats cultes** en *-itat*, *-itzar* i similars, encara que la paraula primitiva tinga diftong, i es manté en els **derivats** on la vocal passa a àtona. També marca la *i* intervocàlica que no fa diftong amb cap vocal (*agraïa*, *traduïen*).", "table": {"head": ["primitiva", "derivada"], "rows": [["*laic*", "*laïcisme*"], ["*europeu*", "*europeïtat*"], ["*arcaic*", "*arcaïtzar*"], ["*fluid*", "*fluïdesa*"], ["*gratuït*", "*gratuïtat*"]]}}, {"title": "Estalvi de la dièresi i excepcions", "text": "No es posa dièresi si la paraula ja porta **accent** (*país*, *incloíem*), amb els sufixos **-isme/-ista** (*egoisme*), en l'infinitiu, gerundi, futur i condicional dels verbs en vocal + *-ir* (*traduirien*), amb **h** intercalada (*vehicle*), en les terminacions **-um/-us** (*aquàrium*, *Màrius*) i darrere de **prefix** (*biunívoc*, *reunió*). Excepcions: *proïsme*, *lluïsme*, *reüll* i les formes rizotòniques de *reeixir* i *sobreeixir*.", "examples": ["*Agraíem* l'ajuda, però ells l'*agraïen*.", "Si t'hi esforces, segur que *reïxes*."], "watch": [{"wrong": "El seu altruïsme és admirable.", "right": "El seu altruisme és admirable."}]}, {"title": "Compostos amb guionet", "text": "Porten guionet els compostos amb **punt cardinal**, els **reduplicatius**, els patrimonials amb el segon element en **r-, s-, x-** i el primer acabat en vocal, els que tenen el primer element **accentuat**, els que poden dificultar la lectura (*pit-roig*), els **direccionals** (*València-Alacant*) i el **no** lexicalitzat com a prefix (*no-agressió*). Atenció: *usdefruit* va junt per tradició.", "table": {"head": ["cas", "exemples"], "rows": [["r-, s-, x-", "*gira-sol*, *esclata-sang*, *para-xocs*"], ["primer element accentuat", "*pèl-roig*, *mà-llarg*, *despús-ahir*"], ["no prefix lexicalitzat", "*pacte de no-agressió*, *el no-res*"], ["direccionalitat", "*míssil terra-aire*, *pàgines 250-278*"]]}}, {"title": "Paraules no simples sense guionet", "text": "Com a norma general, els **compostos** van junts (*pocavergonya*, *capicua*), igual que els **adjectius coordinats** unitaris (*politicoeconòmic*), els **prefixats** (*exministre*), les formacions **grecollatines** (*cardiovascular*) i els **derivats de numerals** (*noucentisme*). El prefix va **separat** davant d'una locució (*ex alt càrrec*), d'una paraula amb guionet, sigla o xifra (*anti nord-americà*, *ex URSS*, *sub 21*) o si crearia una forma homònima (*pre ocupació*).", "examples": ["Cal la *no proliferació* de fongs; s'ha enfadat per un *no res*.", "Un tractat *hispano-americà* (cada membre per separat), però la literatura *hispanoamericana*."]}, {"title": "Pronoms febles: abans o darrere del verb", "text": "El mateix pronom canvia de forma segons la posició: **reforçada** davant de consonant (*el porta*), **elidida** davant de vocal (*l'ha portat*), **plena** darrere de consonant o de diftong decreixent (*portar-lo*, *porteu-lo*) i **reduïda** darrere de vocal (*porta'l*). El pronom *la* no té forma reduïda (*porta-la*) i no s'apostrofa davant de *i*, *u* àtones (*la utilitza*).", "table": {"head": ["davant cons.", "davant vocal", "darrere cons.", "darrere vocal"], "rows": [["*el porta*", "*l'ha portat*", "*portar-lo*", "*porta'l*"], ["*em mira*", "*m'escolta*", "*mirar-me*", "*mira'm*"], ["*els mira*", "*els escolta*", "*mirar-los*", "*mira'ls*"], ["*la mira*", "*l'escolta* / *la utilitza*", "*mirar-la*", "*mira-la*"]]}}, {"title": "Combinacions de pronoms", "text": "En les combinacions, l'apòstrof va **tan a la dreta com siga possible** (*se n'ha anat*, *se'n va anar*; *li l'he portat*, *li'l vaig portar*). En primer lloc d'una combinació anteposada, *em*, *et*, *es* prenen la forma **plena** (*me la van regalar*), però s'elidixen davant de *ho* i *hi* (*m'ho diràs*). Darrere d'un pronom acabat en *-s*, el segon pren la forma **reforçada** (*emportem-nos-els*).", "examples": ["Vol *dir-m'ho*, però encara no *m'ho* ha dit.", "*Compra-te-la* demà; *vendre'ls* no és fàcil."], "watch": [{"wrong": "Se n'anirem demà. Aneu-se'n!", "right": "Ens n'anirem demà. Aneu-vos-en!"}]}], "remember": ["Derivats cultes amb hiat: *laïcisme*, *europeïtat*, *arcaïtzar*, *fluïdesa*.", "Sense dièresi: accent, *-isme/-ista*, *-um/-us*, prefix, h intercalada i infinitiu, gerundi, futur i condicional.", "Excepcions amb dièresi: *proïsme*, *lluïsme*, *reüll*, *reïx*, *sobreïx*.", "Guionet: *gira-sol*, *pèl-roig*, *no-agressió*; junts: *pocavergonya*, *exministre*, *noucentisme*; separats: *ex alt càrrec*, *anti nord-americà*.", "*El porta*, *l'ha portat*, *portar-lo*, *porta'l*, *porteu-lo*; *me la* van regalar; *ens n'anirem*."], "sources": [{"gram": "GVB", "section": "8.1", "title": "Usos de la dièresi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=8_1"}, {"gram": "GVB", "section": "8.2", "title": "Estalvi en l'ús de la dièresi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=8_2"}, {"gram": "GVB", "section": "9.1", "title": "Usos del guionet", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=9_1"}, {"gram": "GVB", "section": "9.2", "title": "Casos sense guionet", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=9_2"}, {"gram": "GVB", "section": "26.3.2", "title": "Formes plenes, reforçades, reduïdes i elidides", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=26_3_2"}, {"gram": "GVB", "section": "26.4.2", "title": "La forma dels pronoms febles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=26_4_2"}, {"gram": "GNV", "section": "5.2", "title": "La dièresi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=5_2"}, {"gram": "GNV", "section": "5.3", "title": "El guionet", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=5_3"}, {"gram": "GNV", "section": "22.3.2", "title": "Formes plenes, reforçades, reduïdes i elidides", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=22_3_2"}, {"gram": "GNV", "section": "22.4.2", "title": "La forma dels pronoms febles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=22_4_2"}]}},
  {"type": "c1_fon_apostrofacio", "lesson": {"intro": "Aprendràs les excepcions a l'apostrofació de l'article i de la preposició *de* (hores, lletres, xifres, sigles, h aspirada, s líquida), les contraccions amb *a*, *de*, *per* i *ca*, i a distingir parònims que només es diferencien per un apòstrof.", "blocks": [{"title": "La regla general i els límits", "text": "*El*, *la*, *de* i els articles personals *en*, *na* s'apostrofen davant de vocal o *h* muda (*l'hora*, *d'herbes*, *n'Úrsula*). Però *la* i *na* no s'apostrofen davant de *i*, *u* **àtones** (*la universitat*, *na Isabel*), i cap d'ells davant de *i*, *u* **semivocals** (*el iogurt*, *el huitanta*, *de hui*, *de Huelva*).", "examples": ["*L'illa* i *l'ungla* (i, u tòniques), però *la il·lusió* i *la unitat* (i, u àtones)."], "watch": [{"wrong": "Les notícies del dia d'hui.", "right": "Les notícies del dia de hui."}]}, {"title": "Homofonia i noms de lletres", "text": "Per evitar confusions, *la* no s'apostrofa davant de ***una*** quan és l'hora (*la una*, però *ni l'una ni l'altra*), ni davant d'***ira*** (per no confondre-la amb *la lira*) ni de ***host*** (per *l'os*). Tampoc *la* ni *de* s'apostrofen davant del **nom de les lletres**: *la a*, *la efe*, *la eme*, *davant de ics*. Sí que s'apostrofa davant de lletres d'altres alfabets: *l'alfa*.", "table": {"head": ["sense apòstrof", "motiu"], "rows": [["*a la una en punt*", "hora del dia (però *ni l'una ni l'altra*)"], ["*la ira del rei*", "no confondre-la amb *la lira*"], ["*la host del rei*", "no confondre-la amb *l'os*"], ["*la eme*, *la hac*", "nom de lletra (però *l'alfa*)"]]}}, {"title": "Xifres, abreviatures i sigles", "text": "Davant de **xifres** i **abreviatures** s'apostrofa segons com es lligen: *l'1 de setembre*, *d'11 milions*, *l'XI Congrés*, *l'art. 13*, *l'Hble. Conseller*. Les **sigles** llegides com a paraula seguixen la regla general (*l'ONU*, *l'IVAM*, *la UNESCO*); les que es **lletregen** es tracten pel nom de les lletres: *l'ONG* (oenegé), *l'FMI* (efeemeí), *la UGT* (ugeté), *la ITV* (itevé).", "table": {"head": ["sigla", "es llig", "article"], "rows": [["ONU", "o-nu", "*l'ONU*"], ["UNESCO", "u-nes-co", "*la UNESCO*"], ["FMI", "efeemeí", "*l'FMI*"], ["UGT", "ugeté", "*la UGT*"], ["UJI", "ú-ji", "*l'UJI*"]]}}, {"title": "H aspirada, s líquida i usos metalingüístics", "text": "Davant de **h aspirada** es manté la forma plena: *el hobby*, *la Hansa*, *de Hollywood*. Davant de **s líquida**, *la* i *de* no s'apostrofen (*la Scala*, *de Strauss*) i *el* admet les dues opcions (*el speaker* o *l'speaker*); els préstecs adaptats amb *e-* seguixen la regla (*l'estrés*). Davant de citacions i títols s'apostrofa (*d'«inaudit»*), però amb valor **metalingüístic** és preferible la forma plena: *el plural de home*.", "watch": [{"wrong": "L'hobby de l'Scala.", "right": "El hobby de la Scala."}]}, {"title": "Contraccions: al, del, pel, cal", "text": "*El* i *els* es contrauen amb *a*, *de*, *per* i amb ***ca*** (casa): *al*, *del*, *pel*, *als*, *dels*, *pels*, *cal*, *cals*. Davant de vocal, si l'article s'apostrofa, la contracció **es desfà**: *a l'amic*, *per l'aire*, *ca l'apotecari*; si no s'apostrofa, es manté: *del iogurt*. L'article que forma part d'un **nom propi** o d'un **topònim no adaptat** no es contrau: *d'El Corte Inglés*, *a El Salvador* (però *al Campello*).", "examples": ["Sopem *cal* metge i dinem *ca l'*apotecari.", "Vaig parlar *a l'*alcalde i *als* regidors."]}, {"title": "Parònims amb apòstrof", "text": "L'apòstrof distingix paraules que sonen igual: *descriure* (verb) / *d'escriure* (de + escriure); *banyat* (participi) / *banya't* (imperatiu + pronom); *rentat* / *renta't*; *portal* (nom) / *porta'l* (imperatiu + pronom). Cal pensar en la **funció** de la paraula en la frase: si hi ha una preposició o un pronom feble, l'apòstrof ho marca; si és una sola paraula (verb, participi o nom), s'escriu tota junta.", "table": {"head": ["sense apòstrof", "amb apòstrof"], "rows": [["*És difícil descriure-ho.*", "*Té ganes d'escriure.*"], ["*Estàs tot banyat.*", "*Banya't en la platja!*"], ["*Obri el portal.*", "*El quadre, porta'l ací.*"]]}}], "remember": ["*La* no s'apostrofa davant de *i*, *u* àtones, ni davant de *una* (hora), *ira*, *host* ni noms de lletres.", "Ni article ni *de* s'apostrofen davant de semivocals (*el iogurt*, *de hui*) ni de *h* aspirada (*el hobby*).", "Xifres, abreviatures i sigles: segons com es lligen (*l'11*, *l'art.*, *l'ONG*, *la UGT*).", "Contraccions *al*, *del*, *pel*, *cal*; es desfan davant de vocal (*a l'amic*, *ca l'apotecari*).", "Parònims: *descriure* / *d'escriure*, *banyat* / *banya't*, *portal* / *porta'l*."], "sources": [{"gram": "GVB", "section": "10.2", "title": "L'apostrofació de l'article definit", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_2"}, {"gram": "GVB", "section": "10.5", "title": "L'Apostrofació davant de i o u no vocàliques", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_5"}, {"gram": "GVB", "section": "10.6", "title": "L'apostrofació davant de h aspirada", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_6"}, {"gram": "GVB", "section": "10.7", "title": "L'apostrofació davant de s líquida", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_7"}, {"gram": "GVB", "section": "10.8", "title": "L'apostrofació davant de paraules homòfones", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_8"}, {"gram": "GVB", "section": "10.9", "title": "L'apostrofació davant del nom de les lletres", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_9"}, {"gram": "GVB", "section": "10.11", "title": "L'apostrofació davant de números", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_11"}, {"gram": "GVB", "section": "10.13", "title": "L'apostrofació davant de sigles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_13"}, {"gram": "GVB", "section": "10.14", "title": "L'apostrofació dels pronoms febles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_14"}, {"gram": "GVB", "section": "11.1", "title": "Formació de les contraccions", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=11_1"}, {"gram": "GVB", "section": "11.2", "title": "Descomposició de les contraccions", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=11_2"}, {"gram": "GVB", "section": "19.2.2", "title": "Formes contractes de l'article", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=19_2_2"}, {"gram": "GNV", "section": "5.4", "title": "L'apòstrof", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=5_4"}]}},
  {"type": "c1_fon_oclusives", "lesson": {"intro": "Aprendràs a escriure les oclusives en final de síl·laba i de paraula (cabdill, apte, dissabte, cognom, fluid, quietud), a evitar la vocal de suport (absurd, immund), les excepcions en -leg i -ec, i a distingir quan/quant, tan/tant i altres parònims.", "blocks": [{"title": "B o p en final de síl·laba", "text": "S'escriuen amb *b* les síl·labes inicials **ab-, abs-, ob-, obs-, sub-, subs-** (*abdicar*, *obstruir*, *substitució*), però amb *p* **apte, opció, òptica, òptim**. La síl·laba **cap-** va amb *p* (*capçal*, *captiu*), però **cabdal, cabdell, cabdill** van amb *b*. En interior de paraula, *p* davant de *c, s, n, t* (*egipci*, *hipnòtic*, *repte*), excepte **dissabte, dubte, sobte**.", "table": {"head": ["regla", "excepcions"], "rows": [["*ab-*, *ob-*, *sub-*: *absurd*, *objecte*, *substitució*", "*apte*, *opció*, *òptim*"], ["*cap-*: *capçal*, *captiu*", "*cabdal*, *cabdell*, *cabdill*"], ["*p* davant de *t*: *repte*, *captar*", "*dissabte*, *dubte*, *sobte*"]]}}, {"title": "D/t i g/c en final de síl·laba", "text": "La síl·laba inicial **ad-** + consonant va amb *d* (*admetre*, *adjudicar*), però **atles, atleta, atlàntic, atmosfera** van amb *t*. Davant de *c, t, s* s'escriu *c* (*acció*, *dacsa*); davant de *d, m, n*, *g*: *amígdala*, *fragment*, *cognom*. Excepcions cultes amb *c*: **anècdota, tècnic, dracma, aràcnid, pícnic**.", "examples": ["L'*atleta* va *admetre* que l'*atmosfera* era tensa.", "Un *tècnic* va contar una *anècdota* del seu *cognom*."]}, {"title": "Final de paraula: regla i excepcions", "text": "En **aguda darrere de vocal** s'escriu *p*, *t*, *c*: *grup*, *blat*, *batec*. Excepcions: amb *b* **adob, aljub, club, esnob, tub**; amb *d* **almud, fluid, fred, sud** i els noms cultes en **-etud, -itud** (*quietud*, *solitud*, *multitud*); amb *g* cultismes i manlleus com **demagog, mag, buldog**. Darrere de consonant o en paraula plana, decidix el **derivat**: *verd* (*verdós*), *àrid* (*aridesa*), *serp* (*serpentí*).", "watch": [{"wrong": "Necessite solitut i quietut.", "right": "Necessite solitud i quietud."}]}, {"title": "Sense vocal de suport; -leg i les excepcions en -ec", "text": "Evita la *-e* de suport per influència castellana: **absurd**, **immund**, **àcid**, **sòlid** (femenins *absurda*, *immunda*...). En les **planes**, *g* o *c* segons els derivats: *diàleg* (*dialogar*), *psicòleg* (*psicologia*), *pròleg*, *catàleg*, *pròdig*. Però s'escriuen amb *c* encara que tinguen derivats amb *g*: **càrrec, espàrrec, bròfec, aràbic**.", "table": {"head": ["incorrecte", "correcte"], "rows": [["*absurde*", "*absurd*"], ["*immunde*", "*immund*"], ["*diàlec*", "*diàleg*"], ["*càrreg*", "*càrrec*"]]}}, {"title": "Homòfons i parònims amb oclusives", "text": "**Quan** és temporal; **quant** demana o expressa quantitat (*quant costa*, *quant a*). **Tan** va davant d'adjectiu o adverbi; **tant** modifica un verb o un nom (*tanta gent*). **Cub** és l'hexaedre; **cup**, el recipient del vi. **Multiplicand** és el nombre que es multiplica i **ordenand**, qui rep un orde sagrat; **multiplicant** i **ordenant** són gerundis.", "examples": ["*Quan* arribes, digues-me *quant* t'ha costat.", "No és *tan* difícil: no cal que estudies *tant*.", "Un dau és un *cub*; el raïm es trepitja en el *cup*."]}], "remember": ["*ab-*, *ob-*, *sub-* amb *b*, però *apte*, *opció*, *òptim*; *cap-* amb *p*, però *cabdill*, *cabdal*, *cabdell*.", "*p* davant de *t*, però *dissabte*, *dubte*, *sobte*; *ad-* amb *d*, però *atleta*, *atles*, *atmosfera*.", "Final amb *d*: *fred*, *sud*, *fluid*, *-etud*, *-itud*; amb *b*: *club*, *tub*, *aljub*.", "Sense vocal de suport: *absurd*, *immund*; *-leg* amb *g*, però *càrrec*, *espàrrec*.", "*quan*/*quant*, *tan*/*tant*, *cub*/*cup*, *multiplicand*, *ordenand*."], "sources": [{"gram": "GVB", "section": "3.2.1", "title": "Les consonants b/p, d/t i g/c", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=3_2_1"}, {"gram": "GVB", "section": "6.5", "title": "Les grafies g i c", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_5"}, {"gram": "GVB", "section": "6.7", "title": "Les grafies b i p", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_7"}, {"gram": "GVB", "section": "6.8", "title": "Les grafies d i t", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_8"}, {"gram": "GVB", "section": "29.5", "title": "Quant", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=29_5"}, {"gram": "GVB", "section": "37.2.8", "title": "Tant", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=37_2_8"}, {"gram": "GNV", "section": "1.4.2.1", "title": "Les consonants oclusives en posició final", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_4_2_1"}, {"gram": "GNV", "section": "4.1", "title": "La representació dels sons [g] i [k]", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_1"}, {"gram": "GNV", "section": "4.9", "title": "Les grafies b i p", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_9"}, {"gram": "GNV", "section": "4.11", "title": "Les grafies d i t", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_11"}]}},
  {"type": "c1_fon_b_v", "lesson": {"intro": "Aprendràs les regles avançades de *b* i *v*: les paraules que s'escriuen diferent que en castellà o en francés, les famílies que alternen *b* i *v*, l'excepció de *m* davant de *v* i els homòfons i parònims com *abans*/*avanç* o *probable*/*provable*.", "blocks": [{"title": "Les regles generals", "text": "S'escriu **b** davant de *l* i *r* (*bleda*, *bromera*), darrere de *m* (*embotit*) i quan alterna amb *p* en la mateixa família (*cabut* ↔ *cap*, *saber* ↔ *sap*). S'escriu **v** darrere de *n* (*canviar*, *invent*), quan alterna amb *u* (*blava* ↔ *blau*, *escriviu* ↔ *escriure*) i en l'imperfet de la primera conjugació (*cantava*). En l'estàndard és preferible **distingir** la pronunciació de [b] i [v].", "table": {"head": ["b", "v"], "rows": [["davant de *l*, *r*: *bleda*", "darrere de *n*: *convent*"], ["darrere de *m*: *tomba*", "alterna amb *u*: *neu* → *nevar*"], ["alterna amb *p*: *sap* → *saber*", "imperfet: *parlava*"]]}}, {"title": "Contrastos amb altres llengües", "text": "Moltes paraules **no** coincidixen amb el castellà o el francés. Amb **b** en valencià: *arribar*, *treballar*, *trobar*, *rebentar*, *rebolcar*, *mòbil*, *biga*, *bena*, *berruga*. Amb **v** en valencià: *covard*, *gravar*, *llavi*, *trèvol*, *advocat*, *avorrir*, *govern*, *provar*, *núvol*, *savi*, *fava*, *esvelt*, *cascavell*.", "table": {"head": ["altra llengua", "valencià"], "rows": [["fr. *arriver*, *travailler*", "*arribar*, *treballar*"], ["cast. *reventar*, *revolcar*, *móvil*", "*rebentar*, *rebolcar*, *mòbil*"], ["cast. *cobarde*, *grabar*, *labio*, *trébol*", "*covard*, *gravar*, *llavi*, *trèvol*"], ["cast. *abogado*, *nube*, *haba*", "*advocat*, *núvol*, *fava*"]]}}, {"title": "Famílies que alternen b i v", "text": "Per la diferència entre la forma **patrimonial** i la **culta**, una mateixa família pot alternar *b* i *v*: *calb* / *calvície*, *cervell* / *cerebral*, *avortar* / *abortiu*. També *mòbil* i *mobilitat* van amb *b*, però *moviment* i *movible* amb *v*. Cal memoritzar-les.", "examples": ["El *mòbil* afavorix la *mobilitat*, però no el *moviment*.", "Han estudiat el *cervell* i l'activitat *cerebral*."], "watch": [{"wrong": "Té un mòvil nou i molta movilitat.", "right": "Té un mòbil nou i molta mobilitat."}]}, {"title": "Usos excepcionals: m davant de v", "text": "Davant de *v* s'escriu normalment **n** (*convent*, *enveja*, *canviar*, *invent*), igual que davant de *b*, *p* i *m* s'escriu **m** (*ambició*, *temps*, *immigrant*). Però es manté la **m** davant de *v* quan forma part de determinats prefixos, compostos o cultismes: **tramvia**, **circumval·lar** (*circumval·lació*), **circumveí**, **triumvir**. Són pocs casos i convé memoritzar-los, perquè la pronunciació no ajuda.", "examples": ["Agafarem el *tramvia* fins a la ronda de *circumval·lació*."], "watch": [{"wrong": "El tranvia passa per la carretera de circunval·lació.", "right": "El tramvia passa per la carretera de circumval·lació."}]}, {"title": "Homòfons i parònims amb b i v", "text": "Hi ha parelles de paraules que sonen igual o quasi igual i que només es distingixen per la *b* o la *v*. En estos casos no hi ha cap regla formal: el **significat** decidix la grafia. Pensa en la família de cada paraula: *avanç* ve d'*avançar*, *avís* d'*avisar*, *hivernar* d'*hivern* i *provable* de *provar*. Altres parelles útils: *beure* / *veure*, *botar* / *votar*, *bell* / *vell*.", "table": {"head": ["amb b", "amb v"], "rows": [["*abans* ('anteriorment')", "*avanç* ('acció d'avançar')"], ["*abís* ('precipici')", "*avís* ('advertiment')"], ["*baca* ('portaequipatges del cotxe')", "*vaca* ('animal')"], ["*hibernar* ('passar l'hivern en letargia')", "*hivernar* ('passar l'hivern en un lloc')"], ["*probable* ('que pot passar')", "*provable* ('que es pot provar')"]]}}], "remember": ["*b* davant de *l*, *r*, darrere de *m* i si alterna amb *p*; *v* darrere de *n*, si alterna amb *u* i en *-ava*.", "Amb *b*: *arribar*, *treballar*, *trobar*, *rebentar*, *rebolcar*, *mòbil*.", "Amb *v*: *covard*, *gravar*, *llavi*, *trèvol*, *advocat*, *núvol*.", "*m* davant de *v*: *tramvia*, *circumval·lar*, *circumveí*, *triumvir*.", "*abans*/*avanç*, *abís*/*avís*, *baca*/*vaca*, *hibernar*/*hivernar*, *probable*/*provable*."], "sources": [{"gram": "GVB", "section": "2.2", "title": "La consonant v", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_2"}, {"gram": "GVB", "section": "6.7", "title": "Les grafies b i p", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_7"}, {"gram": "GVB", "section": "6.19", "title": "Les grafies m, n i mp", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_19"}, {"gram": "GVB", "section": "6.24", "title": "Les grafies b i v", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_24"}, {"gram": "GNV", "section": "1.3.2.2", "title": "Les consonants fricatives labiodentals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_2"}, {"gram": "GNV", "section": "4.10", "title": "Les grafies b i v", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_10"}, {"gram": "GNV", "section": "4.12", "title": "Les grafies m, n, mp, tm i tn", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_12"}]}},
  {"type": "c1_fon_alveolars", "lesson": {"intro": "Aprendràs a resoldre els casos difícils de les alveolars: verbs en -issar, -isar i -itzar, la tz i la z excepcionals, les paraules en -si, els plurals de les paraules en -s, els cultismes amb s/ss i els homòfons i parònims més freqüents.", "blocks": [{"title": "-issar, -isar o -itzar?", "text": "Per a triar la terminació d'un verb, cal fixar-se en el **so** i en l'**origen**. Si la s entre vocals és **sorda**, s'escriu ***-issar*** (*acarnissar-se*, *arrissar*); si és **sonora** i el verb ve d'una paraula amb *s*, ***-isar*** (*matís* → *matisar*, *avís* → *avisar*). El sufix verbal culte és sempre ***-itzar***, pronunciat amb [z]: *polititzar*, *analitzar*, *paralitzar*, *utilitzar*.", "table": {"head": ["terminació", "so", "exemples"], "rows": [["*-issar*", "[s]", "*acarnissar-se*, *arrissar*"], ["*-isar*", "[z]", "*matisar*, *avisar*, *revisar*, *improvisar*"], ["*-itzar*", "[z]", "*polititzar*, *realitzar*, *analitzar*"]]}, "watch": [{"wrong": "analisar, paralisar, utilisar", "right": "analitzar, paralitzar, utilitzar"}]}, {"title": "tz i z excepcionals, paraules en -si i arabismes", "text": "A banda dels numerals (*dotze*, *tretze*, *setze*) i del sufix *-itzar*, el dígraf ***tz*** apareix en paraules com *Natzaret*, *atzar*, *dotzena* o *magatzem*. Entre vocals el so [z] s'escriu amb *s*, però alguns **cultismes i préstecs** porten ***z***: *espermatozoide*, *trapezi*, *bizantí*, *protozou*. Les paraules en **vocal + *-si*** no porten *-s* final en singular: *la crisi*, *la tesi*, *la dosi*, *l'oasi*, *l'emfiteusi*. Atenció als **arabismes** *safrà* i *tassa*.", "watch": [{"wrong": "la crisis, una tesis, la dosis", "right": "la crisi, una tesi, la dosi"}, {"wrong": "Nazaret, azafrà, una taça", "right": "Natzaret, safrà, una tassa"}]}, {"title": "El plural de les paraules en -s", "text": "Les paraules masculines acabades en *-s* fan el plural en ***-os***. Si en el plural la *s* sona **sonora** [z], s'escriu una sola *s*: *pis* → *pisos*, *obés* → *obesos*, *avís* → *avisos*. Si sona **sorda** [s], es **duplica**: *arcabús* → *arcabussos*, *os* → *ossos*, *interés* → *interessos*. La forma femenina dels adjectius seguix el mateix criteri: *obesa*, però *espessa*.", "table": {"head": ["s sonora: una s", "s sorda: ss"], "rows": [["*pis* → *pisos*", "*arcabús* → *arcabussos*"], ["*obés* → *obesos*, *obesa*", "*espés* → *espessos*, *espessa*"], ["*gas* → *gasos*", "*os* → *ossos*"], ["*francés* → *francesos*", "*fracàs* → *fracassos*"]]}}, {"title": "Cultismes, compostos i derivats amb s/ss", "text": "En els cultismes, la *s* entre vocals que sona **sonora** s'escriu *s* (*decisió*, *divisió*, *precisió*), i la que sona **sorda**, *ss*: terminacions ***-gressió***, ***-pressió*** i ***-missió***. Cal pronunciar-les sordes, sense sonoritzar-les. En compostos i derivats cultes es **manté la s simple** del segon formant (*aerosol*, *asèptic*, *asimetria*, *antisocial*), però en altres derivats consolidats s'escriu ***ss***: *pressentir*, *assenyalar*.", "examples": ["La **comissió** va prendre una **decisió** sobre la **transmissió** de les dades.", "Un esprai d'**aerosol** en un ambient **asèptic**."], "watch": [{"wrong": "agresió, impresió, comisió", "right": "agressió, impressió, comissió"}, {"wrong": "decissió, assèptic", "right": "decisió, asèptic"}]}, {"title": "Homòfons i parònims", "text": "Alguns parells sonen igual i només els distingix l'**escriptura** (**homòfons**), i altres es diferencien pel caràcter **sord o sonor** de la consonant (**parònims**). En els parònims, pronunciar bé la [s] i la [z] evita confusions: *caça* [s] / *casa* [z], *cinc* [s] / *zinc* [z].", "table": {"head": ["parella", "significats"], "rows": [["*cella* / *sella*", "pèl de damunt de l'ull / seient del cavall"], ["*cent* / *sent*", "numeral / del verb *sentir*"], ["*cessió* / *sessió*", "acció de cedir / reunió, funció"], ["*abraçar* / *abrasar*", "estrényer amb els braços / cremar"], ["*braça* / *brasa*", "mesura, estil de natació / carbó encés"], ["*dessolar* / *desolar*", "llevar la sola / devastar"], ["*peces* / *peses*", "de *peça* / de *pesar*"], ["*sona* / *zona*", "de *sonar* / àrea"]]}}], "remember": ["*-issar* si la s és sorda, *-isar* si és sonora, *-itzar* per al sufix verbal culte: *acarnissar-se*, *matisar*, *polititzar*.", "*Natzaret*, *atzar* i *magatzem* porten *tz*; *espermatozoide* i *trapezi*, *z* entre vocals.", "En singular, *la crisi*, *la tesi*, *la dosi* i *l'oasi*, sense *-s*.", "Plural en *-os*: una *s* si sona sonora (*pisos*, *obesos*), *ss* si sona sorda (*arcabussos*, *ossos*).", "*Decisió*, però *agressió*, *impressió*, *comissió*; *aerosol* i *asèptic*, però *pressentir* i *assenyalar*.", "Distingix *cella*/*sella*, *cessió*/*sessió*, *abraçar*/*abrasar* i *cinc*/*zinc*."], "sources": [{"gram": "GNV", "section": "1.3.2.3", "title": "Les consonants sibilants alveolars", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_3"}, {"gram": "GVB", "section": "2.3", "title": "Les consonants s/z i ts/tz", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_3"}, {"gram": "GNV", "section": "4.2.1", "title": "La grafia s", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_2_1"}, {"gram": "GNV", "section": "4.2.2", "title": "La grafia ss", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_2_2"}, {"gram": "GNV", "section": "4.3", "title": "La representació del so [z]: les grafies s i z", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_3"}, {"gram": "GNV", "section": "4.4", "title": "La grafia tz", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_4"}, {"gram": "GVB", "section": "6.13", "title": "Les grafies s i ss", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_13"}, {"gram": "GVB", "section": "6.15", "title": "Les grafies z i s", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_15"}, {"gram": "GVB", "section": "6.16", "title": "La grafia tz", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_16"}, {"gram": "GNV", "section": "11.2", "title": "La formació del plural", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=11_2"}, {"gram": "GVB", "section": "17.2", "title": "La formació del plural", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=17_2"}, {"gram": "GVB", "section": "18.2", "title": "El plural dels adjectius", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=18_2"}]}},
  {"type": "c1_fon_palatals", "lesson": {"intro": "Aprendràs a escriure els verbs en -tjar i -jar, les paraules amb j davant de e, els diversos valors de la x (inclosa la x inicial fricativa) i a evitar les confusions palatals que vénen del castellà.", "blocks": [{"title": "Verbs en -tjar i -jar", "text": "El verb seguix la grafia de la paraula de què deriva. Si la base porta ***tg*** o *g* final darrere de *i* (*viatge*, *hostatge*, *jutge*, *desig*), el verb porta ***tj***: *viatjar*, *hostatjar*, *jutjar*, *desitjar*. Si la base acaba en ***-eig*** o ***-aig*** (*mareig*, *passeig*, *assaig*), el verb porta ***j***: *marejar*, *passejar*, *assajar*. En la conjugació, davant de *e*, *i*, ***j*** passa a ***g*** i ***tj*** a ***tg***.", "table": {"head": ["base", "infinitiu", "davant de e"], "rows": [["*hostatge*", "*hostatjar*", "*hostatgem*"], ["*viatge*", "*viatjar*", "*viatgeu*"], ["*mareig*", "*marejar*", "*que et mareges*"], ["*passeig*", "*passejar*", "*passegem*"]]}}, {"title": "La j davant de e", "text": "Davant de *e*, *i*, el so [ʤ] s'escriu normalment amb ***g*** (*gent*, *àgil*). Per raons etimològiques, però, s'escriu ***j*** davant dels grups ***-ecc-*** i ***-ect-*** (*injecció*, *injectable*, *objecte*, *projecte*, *trajecte*) i en algunes paraules com *jerarquia*, *jeroglífic*, *jersei*, *majestat* i *jesuïta*. En estos grups, la *j* es pronuncia [ʤ]: pronunciar-la com una *i* [j] no és recomanable.", "watch": [{"wrong": "gerarquia, magestat, gersei", "right": "jerarquia, majestat, jersei"}, {"wrong": "projecte pronunciat [pɾojɛ́kte]", "right": "projecte [pɾoʤɛ́kte]"}]}, {"title": "Els valors de la x", "text": "La *x* no sempre és palatal. Sona ***[ks]*** entre vocals, davant de consonant sorda i a final (*taxa*, *màxim*, *explosió*, *annex*), i ***[gz]*** en *ex-* i *inex-* inicials seguits de vocal, *h* o consonant sonora (*examen*, *exacte*, *exhortar*, *exdiputat*, *inexorable*). Pronunciar *examen* amb [ks] o *exercici* amb [eʤ] no és recomanable; [ejʃ] (*exemple*) és acceptable on és propi.", "table": {"head": ["so", "context", "exemples"], "rows": [["[ks]", "entre vocals, davant de consonant sorda, final", "*taxa*, *fixar*, *extens*, *annex*"], ["[gz]", "*ex-*, *inex-* + vocal, *h* o consonant sonora", "*examen*, *exhortar*, *exdiputat*"], ["[ʃ]", "darrere de *i*, i en alguns casos a l'inici", "*caixa*, *coixí*, *Xàtiva*"], ["[ʧ]", "a l'inici i darrere de consonant", "*xiquet*, *anxova*, *perxa*"]]}}, {"title": "La x inicial fricativa", "text": "A principi de paraula, la *x* sol sonar africada [ʧ] (*xiquet*, *xafar*), però en molts topònims i cultismes és **fricativa** ***[ʃ]***, com en *caixa*: *Xàbia*, *Xaló*, *Xàtiva*, *Xixona*, *Xavier*, *xenòfob*, *xerografia*, *xilòfon*. No s'hi ha d'afegir cap vocal davant, ni s'ha de pronunciar [s].", "examples": ["Este estiu anirem a **Xàbia** i a **Xaló**.", "El torró de **Xixona** i el castell de **Xàtiva**."], "watch": [{"wrong": "Xàtiva pronunciat [ajʃátiva]", "right": "Xàtiva [ʃátiva]"}, {"wrong": "Jijona", "right": "Xixona"}]}, {"title": "Interferències del castellà", "text": "Moltes errades palatals i oclusives vénen del castellà. En valencià no s'escriu la ***u*** muda castellana en *burgés* (*burgesa*, *burgesia*), *distingir* (*distingit*) o *extingir*. L'impost és la ***taxa***, amb [ks]. El sufix *-aje* castellà correspon a ***-atge***: *missatge*, *garatge*, *equipatge*. I la *j* castellana sovint correspon a ***ix*** [ʃ]: *dibuixar*, *baixar*.", "watch": [{"wrong": "burgués, distinguir, extinguir", "right": "burgés, distingir, extingir"}, {"wrong": "garage, la tasa municipal", "right": "garatge, la taxa municipal"}]}], "remember": ["Base amb *tg* → verb amb *tj* (*hostatjar*); base en *-eig* → verb amb *j* (*marejar*); davant de *e*, *j* → *g* i *tj* → *tg*.", "*J* davant de *e* en *-ecc-*, *-ect-* (*injecció*, *injectable*) i en *jerarquia*, *jeroglífic*, *jersei*, *majestat*, *jesuïta*.", "La *x* pot sonar [ks] (*taxa*), [gz] (*examen*), [ʃ] (*caixa*) o [ʧ] (*xiquet*).", "*Xàbia*, *Xaló*, *Xàtiva*, *Xixona*, *xerografia* i *xilòfon* tenen *x* inicial fricativa [ʃ].", "*Burgés*, *distingir*, *extingir*: sense la *u* del castellà."], "sources": [{"gram": "GNV", "section": "1.3.2.4", "title": "Les consonants sibilants palatals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_4"}, {"gram": "GVB", "section": "2.4", "title": "Les consonants g/j i tg/tj, x/ix", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_4"}, {"gram": "GNV", "section": "4.5", "title": "La representació del so [ʤ]: les grafies g, j, tg i tj", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_5"}, {"gram": "GNV", "section": "4.6", "title": "La representació del so [ʧ]: les grafies x, tx, ig i g", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_6"}, {"gram": "GNV", "section": "4.7", "title": "La representació del so [ʃ]: la grafia x", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_7"}, {"gram": "GNV", "section": "4.8", "title": "La representació del grup fònic [ks]", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_8"}, {"gram": "GVB", "section": "6.10", "title": "Les grafies j i g", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_10"}, {"gram": "GVB", "section": "6.11", "title": "Les grafies tj i tg", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_11"}, {"gram": "GVB", "section": "6.12", "title": "Les grafies x, tx i ig", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_12"}]}},
  {"type": "c1_fon_laterals_nasals", "lesson": {"intro": "Aprendràs on s'escriu l·l en cultismes i derivats, a pronunciar bé la ll sense iodització, a evitar les nasals influïdes per altres llengües i a escriure els grups -mpt-, -mpc-, -mt-, -nt- i -mn-.", "blocks": [{"title": "La l·l: al-, col-, il-, mil-, sil- i -el·la, -il·la", "text": "La ***l·l*** apareix per raons etimològiques en **cultismes**. Una pista útil: les paraules començades per ***al-***, ***col-***, ***il-***, ***mil-*** i ***sil-*** seguides de *l* (*al·legoria*, *col·lecció*, *il·legal*, *mil·lèsim*, *síl·laba*) i moltes acabades en ***-el·la*** i ***-il·la*** (*mortadel·la*, *novel·la*, *til·la*). Atenció a les paraules **patrimonials** amb *ll* palatal: *allargar*, *collita*, *pastilla*, *estrella*.", "table": {"head": ["amb l·l (cultisme)", "amb ll (patrimonial)"], "rows": [["*al·legar*, *al·lusió*", "*allargar*, *allà*"], ["*col·lecció*, *col·legi*", "*collita*, *collar*"], ["*til·la*, *papil·la*", "*pastilla*, *quadrilla*"], ["*novel·la*, *parcel·la*", "*estrella*, *costella*"]]}}, {"title": "Derivats amb l·l", "text": "Alguns derivats cultes de paraules acabades en ***-l*** o en ***-ll*** porten **l·l**: *caramel* → *acaramel·lar*, *estel* → *estel·lar*, *ocel* → *ocel·lar*; *metall* → *metàl·lic*, *moll* → *mol·lície*, *cristall* → *cristal·lí*. També alguns adjectius en *-l* geminen la consonant en el femení: *tranquil·la*, *nul·la*.", "examples": ["Un brillant **metàl·lic** i una aigua **cristal·lina**.", "La pols **estel·lar** i una poma **acaramel·lada**."], "watch": [{"wrong": "metàlic, cristalí, estelar", "right": "metàl·lic, cristal·lí, estel·lar"}]}, {"title": "Cultismes amb l- i amb -l·l-", "text": "Molts cultismes porten ***l*** inicial alveolar, no *ll*: *laboral*, *lingüista*, *lectura*, *línia*, *literatura*; pronunciar-los amb [ʎ] no és recomanable. Altres porten ***l·l*** interior: *cèl·lula*, *cal·ligrafia*, *pel·lícula*, *intel·ligent*, *oscil·lar*. Però no totes les *l* entre vocals són geminades: *galeria*, *milió*, *milionari*, *molècula*.", "watch": [{"wrong": "llaboral, llingüista", "right": "laboral, lingüista"}, {"wrong": "cèlula, caligrafia, mil·lionari", "right": "cèl·lula, cal·ligrafia, milionari"}]}, {"title": "Una ll ben palatal", "text": "La ***ll*** és una lateral **palatal** [ʎ] en qualsevol posició: *llop*, *falla*, *coll*. Pronunciar-la com una *i* semivocal (**iodització**: [jóp], [fája], [kɔ́j]) no és recomanable, com tampoc pronunciar-la [ɲ] en *llenya* o *lligar*. La *l·l* i la *tll* es pronuncien normalment simples: *il·lusió* [iluzió], *bitllet* [biʎét].", "table": {"head": ["paraula", "no recomanable", "estàndard"], "rows": [["*llop*", "[jóp]", "[ʎóp]"], ["*falla*", "[fája]", "[fáʎa]"], ["*coll*", "[kɔ́j]", "[kɔ́ʎ]"], ["*llenya*", "[ɲéɲa]", "[ʎéɲa]"]]}}, {"title": "Nasals: simfonia, impremta, alemanya, canó", "text": "Algunes nasals no coincidixen amb les d'altres llengües: ***simfonia*** (no *sinfonia*), ***impremta*** (no *imprenta*), ***alemanya*** (no *alemana*) i ***canó*** (peça d'artilleria). Per raons etimològiques s'escriuen grups com ***-mpt-*** (*assumpte*, *prompte*, *símptoma*), ***-mpc-*** (*exempció*, *assumpció*), ***-mt-*** (*comte*) i ***-mn-*** (*condemnar*, *solemne*, *himne*, *columna*). La *p* de *-mpt-* i *-mpc-* no sona.", "watch": [{"wrong": "sinfonia, imprenta, condenar", "right": "simfonia, impremta, condemnar"}, {"wrong": "exenció, asunte", "right": "exempció, assumpte"}]}, {"title": "Compte, comte, conte; també, tan bé", "text": "Tres paraules molt pròximes: ***compte*** ('atenció', 'càlcul', 'compte bancari'), ***comte*** (títol nobiliari) i ***conte*** (narració). *Compte* i *comte* sonen igual [kómte]. No confongues ***també*** ('així mateix') amb ***tan bé*** ('de manera tan bona').", "examples": ["Cal anar amb **compte**: el **comte** ens contarà un **conte**.", "Jo **també** hi aniré. Ho ha fet **tan bé** que l'han felicitat."]}], "remember": ["*Al-*, *col-*, *il-*, *mil-*, *sil-* + *l* i moltes paraules en *-el·la*, *-il·la* porten *l·l*: *col·lecció*, *mortadel·la*, *til·la*.", "*Metall* → *metàl·lic*, *cristall* → *cristal·lí*, *caramel* → *acaramel·lar*.", "*Laboral* i *lingüista* amb *l*; *cèl·lula* i *cal·ligrafia* amb *l·l*; *milió* amb *l* simple.", "La *ll* és sempre [ʎ]: evita la iodització ([fája]).", "*Simfonia*, *impremta*, *alemanya*, *canó*; *assumpte*, *exempció*, *condemnar*.", "*Compte* / *comte* / *conte* i *també* / *tan bé*."], "sources": [{"gram": "GNV", "section": "1.3.2.5", "title": "Les consonants laterals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_5"}, {"gram": "GVB", "section": "2.5", "title": "Les consonants l, ll, l·l, tl i tll", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_5"}, {"gram": "GNV", "section": "1.3.2.7", "title": "Les consonants nasals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_7"}, {"gram": "GVB", "section": "2.7", "title": "Les consonants m, n i ny", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_7"}, {"gram": "GNV", "section": "4.12", "title": "Les grafies m, n, mp, tm i tn", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_12"}, {"gram": "GNV", "section": "4.14", "title": "Les grafies l, l·l i tl", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_14"}, {"gram": "GNV", "section": "4.15", "title": "Les grafies ll i tll", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_15"}, {"gram": "GVB", "section": "6.17", "title": "Les grafies l, l·l i tl", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_17"}, {"gram": "GVB", "section": "6.18", "title": "Les grafies ll i tll", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_18"}, {"gram": "GVB", "section": "6.19", "title": "Les grafies m, n i mp", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_19"}, {"gram": "GNV", "section": "13.2.1", "title": "La formació del femení a partir de masculins acabats en consonant", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=13_2_1"}]}},
  {"type": "c1_fon_rotiques_h", "lesson": {"intro": "Aprendràs les formes amb r pròpies del valencià, quan s'emmudix la r (prendre, cerndre, diners, dimarts) i quan no, i com s'escriu la h en mots patrimonials i en cultismes (harmonia, orxata, coet, hemorràgia).", "blocks": [{"title": "Una r on altres llengües no en tenen", "text": "Diverses paraules valencianes tenen **r** on el castellà té **l**: *frare* (fraile), *arbre* (árbol), *marbre* (mármol), *brusa* (blusa). Atenció també a *escorta*: és l'**acompanyament** que protegix algú, mentre que *escolta* és l'acció d'escoltar o el membre d'una organització d'escoltisme. En els **cultismes** es manté la grafia llatina: *derogar*, amb una sola *r*.", "examples": ["El **frare** va plantar un **arbre** davant del convent.", "Porta una **brusa** blanca i una faldeta negra.", "El president viatja amb **escorta**.", "El Parlament ha decidit **derogar** la llei."], "watch": [{"wrong": "una escolta de policies", "right": "una escorta de policies"}]}, {"title": "La r que no sona: prendre i cerndre", "text": "En l'**infinitiu**, el **futur** i el **condicional** de *prendre* i dels seus compostos (*aprendre*, *comprendre*, *emprendre*, *sorprendre*...), la *r* de la primera síl·laba **no es pronuncia**, però **sempre s'escriu**: *prendre* [péndɾe], *emprendré* [empendɾé]. En les altres formes (*comprenc*, *aprenem*) sí que sona. També té una r medial muda *cerndre* ('passar la farina pel sedàs'). En *perdre*, *perdré*, *perdria*, l'emmudiment és **opcional**.", "table": {"head": ["forma", "pronúncia"], "rows": [["*prendre*", "[péndɾe]"], ["*sorprendria*", "[soɾpendɾía]"], ["*comprenc*, *aprenem*", "amb r"], ["*perdre*", "[pɛ́ɾðɾe] o [pɛ́ðɾe]"]]}, "watch": [{"wrong": "Ho apendré prompte.", "right": "Ho aprendré prompte."}]}, {"title": "R que es pot emmudir o pronunciar", "text": "L'AVL admet les dos pronúncies en unes quantes paraules d'ús molt freqüent: *a(r)bre*, *ma(r)bre*, *dine(r)s*, *soco(r)s*, *llavo(r)s* i *dimarts* ([dimáts] o [dimáɾs]). També és **acceptable**, on és propi, emmudir la *r* final de l'infinitiu (*cantar* [kantá]). L'escriptura no canvia: la *r* s'escriu sempre. No confongues este emmudiment opcional amb el de *prendre*, que és el propi de l'estàndard, ni amb els emmudiments **no recomanables** del bloc següent.", "examples": ["*diners*: [dinéɾs] o [dinés]", "*socors*: [sokóɾs] o [sokós]", "*dimarts*: [dimáts] o [dimáɾs]", "*arbre*: [áɾbɾe] o [ábɾe]"]}, {"title": "Pronúncies de la r no recomanables", "text": "No són recomanables en l'estàndard: la **metàtesi** o canvi de lloc de la *r* (*cridar* pronunciat [kiɾdáɾ], *comprar* [kɾompáɾ]); l'**emmudiment** de la *r* de la síl·laba inicial de *problema* o *programa*; l'**addició** d'una *r* final (*compte* [kómteɾ], *creure* [kɾéwɾeɾ]), i l'**emmudiment de la r de l'infinitiu davant de pronom** feble (*portar-li*, *canviar-lo*).", "watch": [{"wrong": "[pobléma], [kɾompáɾ]", "right": "[pɾobléma], [kompɾáɾ]"}, {"wrong": "[poɾtáli] per «portar-li»", "right": "[poɾtáɾli]"}, {"wrong": "[tɾáwɾeɾ] per «traure»", "right": "[tɾáwɾe]"}]}, {"title": "r o rr entre vocals", "text": "El so vibrant [r] s'escriu ***r*** a principi de paraula i darrere de consonant (*rabosa*, *honrat*), i ***rr*** entre vocals (*terra*, *erradicar*, *arrítmia*, *correferent*). Però es manté la ***r*** simple quan seguix un **prefix** o el primer element d'un **compost** acabat en vocal: *contrarestar*, *vicerector*, *semirecta*, *malva-rosa*.", "table": {"head": ["rr entre vocals", "r després de prefix o en compost"], "rows": [["*erradicar*", "*contrarestar*"], ["*arrítmia*", "*vicerector*"], ["*correferent*", "*malva-rosa*"]]}}, {"title": "La h: patrimonials i cultismes", "text": "La ***h*** és normalment **muda** i s'escriu per raons etimològiques, sovint de manera diferent del castellà. Porten h *harmonia*, *hivern*, *subhasta*; no en porten *orxata*, *coet*, *truà*, *ofegar*, *desfer*, *ostatge*, *safanòria*. Els **cultismes** grecs i llatins la conserven: *hèlix*, *hemorràgia*, *híbrid*, *hídric*, *inhalar*, *cohesió*. Sona aspirada només en algunes interjeccions i en derivats de noms estrangers: *ehem*, *hegelià*.", "table": {"head": ["amb h", "sense h"], "rows": [["*harmonia* (armonía)", "*orxata* (horchata)"], ["*subhasta* (subasta)", "*coet* (cohete)"], ["*hivern* (invierno)", "*truà* (truhán)"], ["*hèlix*, *híbrid*, *hídric*", "*ofegar* (ahogar)"]]}}], "remember": ["On el castellà té l, sovint el valencià té r: frare, arbre, marbre, brusa.", "Prendre i compostos: r muda en infinitiu, futur i condicional, però sempre escrita.", "Arbre, diners, socors, dimarts, llavors: r pronunciada o muda, les dos pronúncies valen.", "Res de [pobléma], [kɾompáɾ], [kómteɾ] ni [poɾtáli].", "Harmonia i subhasta amb h; orxata, coet i truà sense h; els cultismes (hèlix, híbrid, hídric) la conserven."], "sources": [{"gram": "GVB", "section": "2.6.1", "title": "Pronunciacions recomanables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_6_1"}, {"gram": "GVB", "section": "2.6.2", "title": "Pronunciacions acceptables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_6_2"}, {"gram": "GVB", "section": "2.6.3", "title": "Pronunciacions no recomanables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_6_3"}, {"gram": "GVB", "section": "6.22", "title": "Les grafies r i rr", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_22"}, {"gram": "GVB", "section": "6.23", "title": "La grafia h", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_23"}, {"gram": "GNV", "section": "1.3.2.6", "title": "Les consonants ròtiques", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_6"}, {"gram": "GNV", "section": "1.4.2.3", "title": "Les consonants vibrants en posició final", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_4_2_3"}, {"gram": "GNV", "section": "4.16", "title": "Les grafies r i rr", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_16"}, {"gram": "GNV", "section": "4.17", "title": "La grafia h", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_17"}]}},
  {"type": "c1_fon_majuscules_abreviacions", "lesson": {"intro": "Aprendràs a distingir la funció demarcativa i la distintiva de les majúscules en els casos més delicats i a escriure bé abreviatures, símbols, sigles i acrònims d'ús freqüent.", "blocks": [{"title": "Funció demarcativa: la posició mana", "text": "La majúscula **demarcativa** depén del lloc: inici de paràgraf, després de **punt** i després de ***?***, ***!*** o ***...*** que **tanquen** la frase. Si no la tanquen, minúscula. Després de **dos punts**, minúscula, excepte en cites textuals i en els documents administratius, on el verb va en majúscules i l'objecte comença amb majúscula. En les **enumeracions**, paraules soltes amb minúscula; oracions, amb majúscula.", "examples": ["En aquella situació tan tensa... **no** em vaig atrevir a dir res.", "SOL·LICITE: **Que** em siga concedida l'ajuda.", "Ell és, com t'ho diria?, **absolutament** imprevisible."]}, {"title": "Funció distintiva: nom propi o nom comú?", "text": "La majúscula **distintiva** singularitza noms propis: persones, institucions, fets històrics, **períodes** (*la Il·lustració*, *el Renaixement*) i **astres** en context astronòmic (*la Terra*, *el Sol*). Van en **minúscula** els noms propis **lexicalitzats** (*un casanova*), els **moviments artístics** (*el gòtic*, *el barroc*), els genèrics de **marques** (*una aspirina*) i de **topònims** (*un xerés*, *un meló d'alger*).", "table": {"head": ["majúscula", "minúscula"], "rows": [["*la Terra gira al voltant del Sol*", "*un sol de justícia*, *lluna plena*"], ["*el Renaixement*", "*el gòtic*, *el cubisme*"], ["*un Volkswagen*", "*una aspirina*, *un jeep*"], ["*Casanova*, el personatge", "*és un casanova*"]]}}, {"title": "Noms de persona, lloc i documents", "text": "Les partícules del cognom van en minúscula darrere del nom (*Isabel de Villena*), però en **majúscula** si l'encapçalen (*el filòsof D'Ors*). En la toponímia urbana, el **genèric** va en minúscula però els càrrecs integrats en el nom, no (*la plaça del Pintor Jacomart*). Els **documents singulars** porten majúscula en totes les paraules significatives (*el Codi Penal*); les **lleis regulars**, només en la primera (*la Llei d'ús i ensenyament del valencià*); les **parts** (*l'article 21*), en minúscula.", "examples": ["la ministra **De** la Vega", "la serra de Mariola, però la **Vall** d'Albaida", "el títol III de la **Constitució** Espanyola"]}, {"title": "Abreviatures: punt, accent, gènere i plural", "text": "Les **abreviatures** acaben amb **punt** (*tel.*, *núm.*, *etc.*) o amb **barra** (*c/*), van en minúscula excepte els **tractaments** (*Sr.*, *Sra.*, *Dra.*) i **conserven l'accent** (*pàg.*, *núm.*). Les de **contracció** fan femení i plural (*Sra.*, *Srs.*); les de **truncament** no tenen gènere (*dir.*) i en plural poden quedar invariables (*pàg.* o *pàgs.*). Els ordinals: *1r*, *4t*, *4a*, *4ts*. El punt abreviatiu fa de punt final i **no se separa** del nom o la xifra a final de línia.", "table": {"head": ["paraula", "abreviatura"], "rows": [["senyor / senyors", "*Sr.* / *Srs.*"], ["número", "*núm.*"], ["carrer", "*c.* o *c/*"], ["quart / quarta", "*4t* / *4a*"]]}, "watch": [{"wrong": "El llibre té 278 pp..", "right": "El llibre té 278 pp."}]}, {"title": "Símbols: sense punt i sense plural", "text": "Els **símbols** són fixats internacionalment: s'escriuen en redona, **sense punt**, sense espais interns i **sense plural** (*km*, *min*, *ha*, *%*, *€*). La majúscula és part de la forma: les unitats que provenen d'un **nom propi** (*W*, watt), els **elements químics** (*Na*), els **punts cardinals** (*N*, *SE*) i els prefixos de grans magnituds (*M*) van en majúscula. Per això el quilowatt és ***kW***.", "watch": [{"wrong": "2 kg. / 15 mins / 30 Ha", "right": "2 kg / 15 min / 30 ha"}, {"wrong": "Kw", "right": "kW"}]}, {"title": "Sigles i acrònims", "text": "Les **sigles** van en majúscula, **sense punts ni espais** ni accents (*IVAM*, *DNI*, *PIB*). Prenen el **gènere** de la primera paraula (*el PIB*, *la CIA*). En plural poden quedar invariables (*les ONG*) o afegir una *s* minúscula (*les ONGs*), mai amb apòstrof; duplicar lletres (*JJOO*) és poc recomanable. Els **acrònims**, fets amb grups de lletres, poden escriure's en majúscules o només amb la inicial: *IVAJ* o *Ivaj*, *Benelux*. Algunes sigles s'han lexicalitzat: *ovni*, *sida*, *làser*.", "examples": ["**el** PIB (el producte interior brut)", "les ONG o les ONGs", "IVAJ o Ivaj; Benelux", "UNESCO es llig com una paraula; UGT, lletra a lletra"], "watch": [{"wrong": "D.N.I. / les ONG's", "right": "DNI / les ONG"}]}], "remember": ["Demarcativa: la posició; distintiva: el nom propi.", "Moviments artístics i noms lexicalitzats, en minúscula; períodes i astres, en majúscula.", "Lleis regulars, només la primera paraula; documents singulars, totes les significatives.", "Abreviatures amb punt (o barra) i accent; tractaments amb majúscula.", "Símbols sense punt i sense plural: 2 kg, 15 min, kW.", "Sigles sense punts, amb el gènere de la primera paraula; acrònims, IVAJ o Ivaj."], "sources": [{"gram": "GVB", "section": "12.1", "title": "Introducció", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=12_1"}, {"gram": "GVB", "section": "12.4", "title": "Inici d'enumeracions", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=12_4"}, {"gram": "GVB", "section": "12.9", "title": "Noms propis referits a persones", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=12_9"}, {"gram": "GVB", "section": "12.24", "title": "Noms de moviments artístics i culturals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=12_24"}, {"gram": "GVB", "section": "12.26", "title": "Noms de lloc lexicalitzats", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=12_26"}, {"gram": "GVB", "section": "12.32", "title": "Títols de documents oficials", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=12_32"}, {"gram": "GVB", "section": "14.2", "title": "Les abreviatures", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=14_2"}, {"gram": "GVB", "section": "14.2.10", "title": "El nombre de les abreviatures", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=14_2_10"}, {"gram": "GVB", "section": "14.3", "title": "Els símbols", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=14_3"}, {"gram": "GVB", "section": "14.4", "title": "Les sigles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=14_4"}, {"gram": "GNV", "section": "6.1.2", "title": "La funció demarcativa", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=6_1_2"}, {"gram": "GNV", "section": "6.1.3", "title": "La funció distintiva", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=6_1_3"}, {"gram": "GNV", "section": "6.3", "title": "Les abreviacions", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=6_3"}]}},
  {"type": "c1_fon_puntuacio", "lesson": {"intro": "Aprendràs les regles d'ús de tots els signes de puntuació, des dels usos menys freqüents de la coma i els dos punts fins als claudàtors, l'asterisc i la barra, i com es combinen entre ells.", "blocks": [{"title": "La coma en contextos exigents", "text": "A més del vocatiu i els incisos, la coma marca els elements **desplaçats** (*No en vull saber res, de les seues històries*), les **clàusules absolutes** (*Conclòs el tràmit, ...*), el **verb elidit** i les ambigüitats (*Si ve, Joan ho farà*). Es posa davant de ***i*** quan introduïx un **contingut diferent** o unix elements que ja porten coordinacions, i darrere d'***etc.*** si l'enumeració és el subjecte. També separa la **data** en les lleis, el lloc de la data i el carrer del número.", "examples": ["Actuà sense contemplacions, **i** probablement eixe va ser el seu error.", "La creació de plataformes, documentació, etc., és l'objectiu.", "Llei 28/2005, de 26 de desembre, de mesures sanitàries...", "C/ Pintor Maella, 5"], "watch": [{"wrong": "El president va manifestar, que no acudiria.", "right": "El president va manifestar que no acudiria."}]}, {"title": "Punt i coma, punt i dos punts", "text": "El **punt i coma** separa grups que ja porten comes (davant de l'últim, amb *i*, coma) i va davant de connectors com *tanmateix* o *amb tot* en oracions llargues. El **punt** no es posa darrere de **títols aïllats**, **símbols**, **datacions** ni de *?* i *!*, ni separa els milers en **anys** o codis postals. Els **dos punts** introduïxen enumeracions, exemples, cites, causes o conseqüències, i separen hores i minuts (preferible *16:45*), però mai van darrere d'una **preposició**.", "table": {"head": ["incorrecte", "correcte"], "rows": [["*l'any 2.007*", "*l'any 2007*"], ["*Alacant, 30 de juny del 2007.*", "*Alacant, 30 de juny del 2007*"], ["*representants de: Belarús...*", "*representants de Belarús...*"], ["*2 kg.*", "*2 kg*"]]}}, {"title": "Punts suspensius, interrogació i exclamació", "text": "Els **punts suspensius** (tres i només tres) expressen dubte o interrupció, deixen una frase inacabada, fan una pausa emfàtica o insinuen paraules malsonants; entre claudàtors, *[...]*, marquen una **omissió** en una cita. Poden anar seguits de coma o punt i coma, **mai de punt**, i no van darrere d'***etc.*** Els signes ***?*** i ***!*** d'obertura són **opcionals**; els de tancament poden anar seguits de coma, punt i coma o dos punts, però no de punt.", "examples": ["Lladres, roders, assassins**...,** eixa és la gent que hi trobaràs.", "Jo només vull saber tres coses: on**?,** des de quan**?** i per què**?**", "Oh Senyor**!,** sigueu bondadós amb el vostre poble."], "watch": [{"wrong": "el comerç, etc...", "right": "el comerç, etc."}]}, {"title": "Guions, parèntesis i claudàtors", "text": "El **guió** delimita incisos; davant de punt, el de tancament pot ometre's. Els **parèntesis** aporten dades secundàries, **acotacions** teatrals i **opcions de lectura** (*el(s) seu(s)*); la coma o el punt i coma que coincidix amb el tancament va **darrere**. Els **claudàtors** marquen omissions *[...]*, **aclariments** dins d'una cita, un parèntesi **dins d'un altre** i les **transcripcions fonètiques**.", "examples": ["¿Pot justificar-se la violència —es preguntà el conferenciant—?", "Cada persona té el(s) seu(s) ritme(s) d'aprenentatge.", "«Nosaltres [els valencians] som mediterranis.»", "*corredor* [koreðó]"]}, {"title": "Les cometes", "text": "Les cometes **baixes** (« »), **altes** (“ ”) i **simples** (‘ ’) es combinen en este orde quan cal citar dins d'una cita. Les dobles marquen **citacions** i títols de **capítols**, **articles**, **conferències** i ponències (els llibres, en cursiva); la cometa de tancament (») també repetix una dada de la línia anterior en llistes. Les **simples** emmarquen el **significat** d'una paraula. Si la cita s'obri dins de la frase, el punt va **fora**.", "examples": ["El capítol segon té com a títol «Qüestions de nomenclatura».", "La paraula *otitis* prové de οὖς ‘orella’ i -itis ‘inflamació’.", "...quan va dir que «la guerra és sempre una derrota»."]}, {"title": "Altres signes: asterisc, barra i secció", "text": "L'**asterisc** (*) crida una **nota** darrere d'una paraula o, en lingüística, marca, col·locat davant, una forma **agramatical**. La **barra** (/) indica opcions (*Senyor/a*), oposició (*nord/sud*), abreviatures i símbols (*c/c*, *km/h*), el número i l'any d'una llei (*Llei 4/1988*), fraccions, **canvis de vers** i dates. La barra invertida (\\) separa directoris, i el **signe de secció** (§) remet a apartats.", "table": {"head": ["signe", "exemple"], "rows": [["asterisc", "crida de nota; forma agramatical"], ["barra", "*Llei 4/1988*; *Senyor/a*; *km/h*"], ["barra (versos)", "*Vora el barranc dels Algadins / hi ha uns tarongers*"], ["secció", "*Vegeu § 15.5.1*"]]}}], "remember": ["Coma davant de i només si canvia el contingut; mai entre verb i complement.", "Sense punt: títols aïllats, símbols, datacions, anys i darrere de ? i !.", "Mai dos punts darrere de preposició.", "Punts suspensius + coma, sí; + punt o darrere d'etc., no.", "Claudàtors: omissió [...], aclariment, parèntesi dins de parèntesi i transcripció fonètica.", "Cometes « » → “ ” → ‘ ’; capítols i articles entre cometes, llibres en cursiva."], "sources": [{"gram": "GVB", "section": "15.2", "title": "Posició dels signes de puntuació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_2"}, {"gram": "GVB", "section": "15.3.1", "title": "Usos de la coma", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_3_1"}, {"gram": "GVB", "section": "15.4", "title": "El punt i coma", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_4"}, {"gram": "GVB", "section": "15.5.3", "title": "Usos incorrectes del punt", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_5_3"}, {"gram": "GVB", "section": "15.6.1", "title": "Usos dels dos punts", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_6_1"}, {"gram": "GVB", "section": "15.7.2", "title": "Combinació dels punts suspensius amb altres signes de puntuació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_7_2"}, {"gram": "GVB", "section": "15.8.2", "title": "Combinació dels signes d'interrogació amb altres signes de puntuació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_8_2"}, {"gram": "GVB", "section": "15.11.1", "title": "Usos dels parèntesis", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_11_1"}, {"gram": "GVB", "section": "15.12", "title": "Els claudàtors", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_12"}, {"gram": "GVB", "section": "15.13.1", "title": "Usos de les cometes", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_13_1"}, {"gram": "GVB", "section": "15.14", "title": "L'asterisc", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_14"}, {"gram": "GVB", "section": "15.15", "title": "La barra inclinada", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_15"}, {"gram": "GNV", "section": "7.2", "title": "Contacte entre signes de puntuació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=7_2"}, {"gram": "GNV", "section": "7.5.3", "title": "Els claudàtors", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=7_5_3"}]}}
]$data$::jsonb) AS l(type text, lesson jsonb)
WHERE r.category = 'fonetica_ortografia' AND r.difficulty = 'C1' AND r.type = l.type;
